import{_ as a}from"./chunks/scalar.DCy0EKw6.js";import{_ as s,o as t,c as n,a5 as o}from"./chunks/framework.BkFmai_x.js";const i="/PasswordManagerApp/screenshots/api/scalar-standalone-response.png",k=JSON.parse('{"title":"API Reference: Overview & Auth","description":"","frontmatter":{},"headers":[],"relativePath":"api/reference.md","filePath":"api/reference.md","lastUpdated":1784304010000}'),r={name:"api/reference.md"};function l(p,e,d,c,h,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="api-reference-overview-auth" tabindex="-1">API Reference: Overview &amp; Auth <a class="header-anchor" href="#api-reference-overview-auth" aria-label="Permalink to &quot;API Reference: Overview &amp; Auth&quot;">​</a></h1><p><code>VaultGuard.API</code> is an ASP.NET Core Web API. It&#39;s the same surface the mobile app and browser extension use, and it runs the exact <code>VaultGuard.Services</code>/<code>VaultGuard.Crypto</code> core the in-process WPF and Blazor clients use - so behaviour is identical everywhere.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>Whatever host you run the API on, e.g. <code>https://localhost:7001</code> in development.</p><h2 id="accessing-scalar" tabindex="-1">Accessing Scalar <a class="header-anchor" href="#accessing-scalar" aria-label="Permalink to &quot;Accessing Scalar&quot;">​</a></h2><p><code>VaultGuard.API</code> serves a full interactive reference UI (<a href="https://scalar.com/" target="_blank" rel="noreferrer">Scalar</a>) of its own, live, for free - no separate tool or account needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{API_BASE_URL}/scalar</span></span></code></pre></div><p>e.g. <code>https://localhost:7001/scalar</code> in development, or <code>https://api.yourdomain.com/scalar</code> once deployed. Every endpoint is browsable there, and each one has a <strong>Test Request</strong> button that lets you fill in headers/body and call your running API directly from the browser - the same client Stripe/Twilio-style docs use, just self-hosted with your instance.</p><p>Prefer staying on this docs site? <strong><a href="/PasswordManagerApp/api/try-it">Try It Live</a></strong> embeds the same client here - point it at your API&#39;s URL and it works identically.</p><blockquote><p><strong>CORS note:</strong> the Test Request panel calls your API straight from your browser, so it&#39;s a real cross-origin request unless you&#39;re browsing from the exact same origin as the API. <code>Cors:AllowedOrigins</code> (see <code>appsettings.json</code>) defaults to <code>localhost</code> variants only - add whatever origin you&#39;re browsing the docs from (e.g. <code>https://dotnetappdev.github.io</code> if using the hosted docs site against a public instance) if requests get blocked.</p></blockquote><p>Below: the standalone <code>/scalar</code> page after clicking <strong>Test Request → Send</strong> on <code>POST /api/ApiKeys/issue</code> - a real request went out and a real response (<code>401 Unauthorized</code>, since no <code>X-API-Key</code> was set) came back in 14ms, shown in the response panel on the right.</p><div class="screenshot-grid"><figure><img src="'+a+'" alt="Scalar endpoint reference"><figcaption>Endpoint reference (sidebar + docs)</figcaption></figure><figure><img src="'+i+`" alt="Scalar live response"><figcaption>Test Request → Send, with a real response</figcaption></figure></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Every endpoint except <code>/health</code>, <code>/scalar</code>, <code>/openapi</code> and <code>/api/authentication/*</code> requires the <code>X-API-Key</code> header.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-API-Key: &lt;your-key&gt;</span></span></code></pre></div><h3 id="getting-a-key" tabindex="-1">Getting a key <a class="header-anchor" href="#getting-a-key" aria-label="Permalink to &quot;Getting a key&quot;">​</a></h3><p><strong>From the web app</strong> (recommended): sign in, go to <strong>Settings → API Keys</strong> (<code>/api-keys</code>), create a named key, copy it immediately - it&#39;s shown once and stored hash-only afterwards.</p><p><strong>Directly from the API</strong>, proving identity with email + master password - useful for scripting or first-time device setup:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/authentication/generate-api-key</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;My Pixel 8&quot;,</span></span>
<span class="line"><span>  &quot;email&quot;: &quot;you@example.com&quot;,</span></span>
<span class="line"><span>  &quot;masterPassword&quot;: &quot;your-master-password&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;414C1BUrIaVHwulgSPZAW1-ELcL--MhSS9Cmx8Z8GZc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;userId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0d6fe338-9517-42cf-aeb7-16410b285da7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;keyName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My Pixel 8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;instructions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Store this API key securely...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The equivalent under <code>/api/apikeys/issue</code> (<code>ApiKeysController.IssueApiKey</code>) does the same thing and is what the desktop/web/mobile &quot;Generate key from server&quot; / &quot;Test connection&quot; flows call.</p><h3 id="session-tokens-for-decrypt-reveal-endpoints" tabindex="-1">Session tokens (for decrypt/reveal endpoints) <a class="header-anchor" href="#session-tokens-for-decrypt-reveal-endpoints" aria-label="Permalink to &quot;Session tokens (for decrypt/reveal endpoints)&quot;">​</a></h3><p>Signing in (<code>POST /api/auth/login/enhanced</code> or <code>/api/auth/login/masterkey</code>) with the <code>X-API-Key</code> header returns a session <strong>token</strong>. Endpoints that decrypt or reveal secrets (<code>/api/passworditems/{id}/decrypt</code>, <code>/api/passworditems/{id}/reveal</code>, <code>/api/auth/qr/generate</code>, OTP setup) additionally require that token as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;token&gt;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/auth/login/enhanced</span></span>
<span class="line"><span>X-API-Key: 414C1BUrIaVHwulgSPZAW1-ELcL--MhSS9Cmx8Z8GZc</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ &quot;email&quot;: &quot;you@example.com&quot;, &quot;password&quot;: &quot;your-master-password&quot; }</span></span></code></pre></div><blockquote><p>The seeded demo account <code>admin@passwordmanager.local</code> uses master key <code>7hm3Z!Csu:Y64nm</code> in a development environment seeded with demo data, handy for trying the flow above immediately.</p></blockquote><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><p>Beyond authentication, most write/read actions on password items go through a permission check (<code>Permissions.Passwords.View/Create/Edit/Delete/ViewSensitive</code>) scoped to the resource owner - a user can only act on their own items unless a parent/child relationship grants otherwise. A missing item and an item you don&#39;t have access to both return <code>404</code>, never <code>403</code>, so an ID can&#39;t be used to enumerate other users&#39; data.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>All request/response bodies are JSON.</li><li>Collection endpoints return arrays directly (not wrapped in an envelope).</li><li>Not-found returns <code>404</code> with a short string message, e.g. <code>&quot;Password item with ID 42 not found&quot;</code>.</li><li>Validation failures return <code>400</code> with <code>ModelState</code> errors.</li><li>Unhandled server errors return <code>500</code> with a generic message (details are logged server-side, not exposed to the client).</li><li>Auth endpoints are rate-limited per-IP more strictly than the rest of the API.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/PasswordManagerApp/api/password-items">Password Items</a> - the core CRUD surface, plus reveal/decrypt.</li><li><a href="/PasswordManagerApp/api/organization">Collections, Categories &amp; Tags</a> - the three organisational axes.</li><li><a href="/PasswordManagerApp/api/users">Users &amp; Settings</a> - profile, admin user management, API key lifecycle.</li></ul>`,32)])])}const y=s(r,[["render",l]]);export{k as __pageData,y as default};
